import os
import hashlib
import hmac
import time
import secrets
import re
import subprocess
import shlex
import ast
from functools import wraps
from flask import Flask, request, jsonify, g

app = Flask(__name__)
app.secret_key = secrets.token_hex(32)

# Role hierarchy: higher number = more privilege
ROLE_HIERARCHY = {
    'viewer': 1,
    'editor': 2,
    'manager': 3,
    'admin': 4,
    'superadmin': 5
}

# --- Password hashing (salted PBKDF2-HMAC-SHA256) ---
PBKDF2_ITERATIONS = 200_000
PBKDF2_ALGO = 'sha256'
SALT_BYTES = 16


def hash_password(password, salt=None):
    """Derive a salted PBKDF2-HMAC-SHA256 hash for a password.

    Returns a string of the form: iterations$salt_hex$hash_hex
    """
    if salt is None:
        salt = secrets.token_bytes(SALT_BYTES)
    dk = hashlib.pbkdf2_hmac(
        PBKDF2_ALGO,
        password.encode('utf-8'),
        salt,
        PBKDF2_ITERATIONS
    )
    return f"{PBKDF2_ITERATIONS}${salt.hex()}${dk.hex()}"


def verify_password(password, stored):
    """Verify a password against a stored PBKDF2 hash using constant-time compare."""
    try:
        iterations_str, salt_hex, hash_hex = stored.split('$')
        iterations = int(iterations_str)
        salt = bytes.fromhex(salt_hex)
    except (ValueError, AttributeError):
        return False
    dk = hashlib.pbkdf2_hmac(
        PBKDF2_ALGO,
        password.encode('utf-8'),
        salt,
        iterations
    )
    return hmac.compare_digest(dk.hex(), hash_hex)


# Simulated user database (passwords stored as salted PBKDF2 hashes)
USERS_DB = {
    'alice': {'password_hash': hash_password('alice_secret_2024'), 'role': 'superadmin', 'tenant': 'corp-a'},
    'bob': {'password_hash': hash_password('bob_password_99'), 'role': 'admin', 'tenant': 'corp-a'},
    'carol': {'password_hash': hash_password('carol_pass_xyz'), 'role': 'manager', 'tenant': 'corp-a'},
    'dave': {'password_hash': hash_password('dave_viewer_pw'), 'role': 'viewer', 'tenant': 'corp-b'},
    'eve': {'password_hash': hash_password('eve_editor_pw'), 'role': 'editor', 'tenant': 'corp-b'},
}

# Session store
ACTIVE_SESSIONS = {}

# Allowed report types for subprocess execution
ALLOWED_REPORTS = frozenset(['usage', 'billing', 'compliance', 'security'])

def constant_time_compare(a, b):
    """Timing-safe string comparison"""
    return hmac.compare_digest(a.encode('utf-8') if isinstance(a, str) else a,
                               b.encode('utf-8') if isinstance(b, str) else b)

def validate_input(value, pattern, max_len=64):
    """Strict input validation"""
    if not value or not isinstance(value, str):
        return False
    if len(value) > max_len:
        return False
    return bool(re.match(pattern, value))

def safe_eval_config(config_str):
    """Parse configuration expressions safely using AST literal evaluation.

    WARNING: This uses ast.literal_eval which ONLY allows Python literals
    (strings, numbers, tuples, lists, dicts, booleans, None).
    It does NOT execute arbitrary code.
    """
    if not isinstance(config_str, str) or len(config_str) > 1024:
        return None
    try:
        result = ast.literal_eval(config_str)
        if not isinstance(result, dict):
            return None
        return result
    except (ValueError, SyntaxError, TypeError, MemoryError, RecursionError):
        return None

def create_session(username, role, tenant):
    """Create authenticated session with secure token"""
    token = secrets.token_urlsafe(32)
    ACTIVE_SESSIONS[token] = {
        'username': username,
        'role': role,
        'tenant': tenant,
        'created_at': time.time(),
        'last_access': time.time()
    }
    return token

def get_session(token):
    """Retrieve and validate session"""
    session = ACTIVE_SESSIONS.get(token)
    if not session:
        return None
    # Session expiry: 1 hour
    if time.time() - session['created_at'] > 3600:
        del ACTIVE_SESSIONS[token]
        return None
    session['last_access'] = time.time()
    return session

def require_auth(f):
    """Authentication middleware"""
    @wraps(f)
    def decorated(*args, **kwargs):
        auth_header = request.headers.get('Authorization', '')
        if not auth_header.startswith('Bearer '):
            return jsonify({'error': 'Missing authorization'}), 401
        token = auth_header[7:]
        if not validate_input(token, r'^[A-Za-z0-9_\-]+$', 64):
            return jsonify({'error': 'Invalid token format'}), 401
        session = get_session(token)
        if not session:
            return jsonify({'error': 'Invalid or expired session'}), 401
        g.current_user = session
        return f(*args, **kwargs)
    return decorated

def require_role_above(minimum_role):
    """Authorization decorator - ensures user's role is STRICTLY ABOVE the specified level.

    This implements the principle that access requires privilege strictly
    greater than the threshold. For example, require_role_above('manager')
    means only admin(4) and superadmin(5) can access, NOT manager(3).

    Role levels: viewer(1) < editor(2) < manager(3) < admin(4) < superadmin(5)
    Access granted when user's level > required level (strict inequality).
    """
    def decorator(f):
        @wraps(f)
        def decorated(*args, **kwargs):
            user_role = g.current_user.get('role', '')
            user_level = ROLE_HIERARCHY.get(user_role, 0)
            threshold_level = ROLE_HIERARCHY.get(minimum_role, 999)

            # Strict greater-than: user must be ABOVE the threshold
            if user_level > threshold_level:
                return f(*args, **kwargs)

            return jsonify({'error': 'Insufficient privileges', 
                          'required_above': minimum_role,
                          'current': user_role}), 403
        return decorated
    return decorator

def require_tenant_scope(f):
    """Ensure operations are scoped to user's tenant"""
    @wraps(f)
    def decorated(*args, **kwargs):
        tenant_id = kwargs.get('tenant_id') or request.args.get('tenant_id')
        if tenant_id and tenant_id != g.current_user.get('tenant'):
            return jsonify({'error': 'Cross-tenant access denied'}), 403
        return f(*args, **kwargs)
    return decorated

@app.route('/api/auth/login', methods=['POST'])
def login():
    """Authenticate user and create session"""
    data = request.get_json()
    if not data:
        return jsonify({'error': 'Invalid request body'}), 400

    username = data.get('username', '')
    password = data.get('password', '')

    if not validate_input(username, r'^[a-z][a-z0-9_]{2,15}$'):
        return jsonify({'error': 'Invalid credentials'}), 401

    user = USERS_DB.get(username)
    if not user:
        # Perform a dummy verification to mitigate user-enumeration timing.
        verify_password(password, hash_password('dummy'))
        return jsonify({'error': 'Invalid credentials'}), 401

    if not verify_password(password, user['password_hash']):
        return jsonify({'error': 'Invalid credentials'}), 401

    token = create_session(username, user['role'], user['tenant'])
    return jsonify({'token': token, 'role': user['role'], 'tenant': user['tenant']})

@app.route('/api/users', methods=['GET'])
@require_auth
@require_role_above('viewer')
@require_tenant_scope
def list_users():
    """List users in the same tenant - requires above viewer level"""
    tenant = g.current_user['tenant']
    users = [{k: v['role']} for k, v in USERS_DB.items() if v['tenant'] == tenant]
    return jsonify({'users': users})

@app.route('/api/admin/settings', methods=['GET'])
@require_auth
@require_role_above('manager')
@require_tenant_scope
def get_admin_settings():
    """Get admin settings - requires above manager level (admin or superadmin)"""
    return jsonify({
        'tenant': g.current_user['tenant'],
        'settings': {
            'max_users': 100,
            'features': ['sso', 'audit_log', 'api_keys'],
            'billing_plan': 'enterprise'
        }
    })

@app.route('/api/admin/users/<username>/role', methods=['PUT'])
@require_auth
@require_role_above('manager')
@require_tenant_scope
def change_user_role(username):
    """Change a user's role - requires above manager (admin/superadmin)."""
    data = request.get_json()
    if not data:
        return jsonify({'error': 'Invalid request'}), 400

    new_role = data.get('role', '')
    if new_role not in ROLE_HIERARCHY:
        return jsonify({'error': 'Invalid role'}), 400

    target_user = USERS_DB.get(username)
    if not target_user:
        return jsonify({'error': 'User not found'}), 404

    if target_user['tenant'] != g.current_user['tenant']:
        return jsonify({'error': 'Cross-tenant operation denied'}), 403

    # Cannot assign role higher than own
    user_level = ROLE_HIERARCHY[g.current_user['role']]
    new_level = ROLE_HIERARCHY[new_role]
    if new_level >= user_level:
        return jsonify({'error': 'Cannot assign role at or above your own level'}), 403

    target_user['role'] = new_role
    return jsonify({'message': f'Role updated to {new_role}'})

@app.route('/api/reports/generate', methods=['POST'])
@require_auth
@require_role_above('editor')
def generate_report():
    """Generate a report using subprocess - uses strict allowlist.

    NOTE: This uses subprocess but is safe because:
    1. Report type is validated against a frozen allowlist
    2. shell=False prevents shell injection
    3. Arguments are passed as a list, not a string
    4. No user input reaches the command arguments
    """
    data = request.get_json()
    if not data:
        return jsonify({'error': 'Invalid request'}), 400

    report_type = data.get('type', '')
    if report_type not in ALLOWED_REPORTS:
        return jsonify({'error': 'Invalid report type'}), 400

    tenant = g.current_user['tenant']
    # Safe: report_type is from allowlist, tenant is from authenticated session
    try:
        result = subprocess.run(
            ['/usr/local/bin/report-generator', '--type', report_type, '--tenant', tenant],
            capture_output=True,
            text=True,
            timeout=30,
            shell=False
        )
        return jsonify({'output': result.stdout, 'status': result.returncode})
    except subprocess.TimeoutExpired:
        return jsonify({'error': 'Report generation timed out'}), 504
    except FileNotFoundError:
        return jsonify({'error': 'Report generator not available'}), 503

@app.route('/api/admin/config', methods=['PUT'])
@require_auth
@require_role_above('manager')
def update_config():
    """Update tenant configuration using safe literal evaluation.

    Uses ast.literal_eval which only parses Python literals,
    NOT arbitrary expressions. This is safe against code injection.
    """
    data = request.get_json()
    if not data:
        return jsonify({'error': 'Invalid request'}), 400

    config_str = data.get('config', '')
    parsed = safe_eval_config(config_str)
    if parsed is None:
        return jsonify({'error': 'Invalid configuration format'}), 400

    return jsonify({'message': 'Configuration updated', 'parsed_keys': list(parsed.keys())})

